-- Lyra Ori Spirit Guardian Painter
-- Programmatically draws an ethereal 2D platformer spirit character across 8 organized layers.

local spr = app.activeSprite
if not spr or spr.width ~= 500 or spr.height ~= 500 then
  spr = Sprite(500, 500)
end

app.transaction("Draw Ori Spirit by Lyra", function()
  local function drawSpans(img, spans)
    for _, span in ipairs(spans) do
      local y, x1, x2, r, g, b, a = span[1], span[2], span[3], span[4], span[5], span[6], span[7]
      local c = Color{ r=r, g=g, b=b, a=a }
      for x = x1, x2 do
        img:drawPixel(x, y, c)
      end
    end
  end

  -- Layer: Forest Spirit Aura
